import{COLORS}from'../../../assets/core.mjs';import{board}from'../../02/teaching/visuals.mjs';import{describeError02}from'../../../assets/legality02.mjs';import{metricsReport}from'../../../assets/metrics03.mjs';import{RUN07,RUN07_SEED3,RUN07_T2,RUN07_T12,COMPARISON07}from'../../../assets/anneal07.mjs';
const E=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;');
const T=(x,y,s,size=24,color='#244d40',anchor='middle')=>`<text x="${x}" y="${y}" font-size="${size}" fill="${color}" text-anchor="${anchor}">${E(s)}</text>`;
const R=(x,y,w,h,fill='#eef4e8',stroke='#b7c9b5',extra='')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3" fill="${fill}" stroke="${stroke}" ${extra}/>`;
const rowsOf=pack=>Object.entries(pack).map(([id,v])=>[id,v.x,v.y,v.w,v.h]).sort((a,b)=>a[0]<b[0]?-1:1);
function cards(items,p){return items.map(([h,b],i)=>{const x=55+(i%2)*455,y=110+Math.floor(i/2)*155;return R(x,y,415,130,'#edf3e8',p*items.length>=i?'#72997e':'#c8d4c6')+T(x+20,y+38,h,25,'#234e40','start')+T(x+20,y+85,b,19,'#58796a','start');}).join('');}
function permChips(before,x,y,hi){const cw=48,gap=12;let s='';before.split('').forEach((ch,i)=>{const h=hi&&hi.includes(ch)&&before.indexOf(ch)===i;s+=R(x+i*(cw+gap),y,cw,48,h?'#f6ead9':'#f2f6ee',h?'#c9a06d':'#c8d4c6')+T(x+i*(cw+gap)+cw/2,y+30,ch,24,h?'#8a5a26':'#355d49');});return s;}
export function renderScene(scene,time,trial,reduced){const p=Math.max(0,Math.min(1,(time-scene.start)/(scene.end-scene.start))),o=scene.outline||[10,8];let rows=trial||scene.rows,body='',moving=false;
 if(!trial&&scene.from){const q=reduced?1:Math.max(0,Math.min(1,(time-scene.start-1)/3)),v=q*q*(3-2*q);moving=q<1;rows=scene.rows.map((r,i)=>r.map((n,j)=>j===1||j===2?scene.from[i][j]+(n-scene.from[i][j])*v:n));}
 const report=metricsReport(rows,o,scene.catalog);
 if(trial){body=board(rows,o,{x:40,y:105,w:570,h:315});body+=T(755,160,report.legal?'当前摆放合法':'先处理摆放错误',27,report.legal?'#326d4d':'#a44f35')+T(755,230,'这是你手动调整后的布局',22,'#5e7565')+T(755,300,'搜索改的是编码，不是坐标',22,'#5e7565');}
 else if(scene.view==='intro-why07'){body=R(150,140,660,110,p>.3?'#f6ead9':'#f3f6ef','#c9a06d')+T(480,185,'五块问题：14400 个序列对编码',30,'#8a5a26')+T(480,225,'真实芯片是天文数字——逐个试不现实',22,'#a04e36');body+=R(150,300,660,90,p>.55?'#e3efdd':'#f2f6ee','#72997e')+T(480,338,'模拟退火：每步只看一个邻居',24,'#355d49')+T(480,372,'用明确的规则决定接受还是拒绝',20,'#5e7565');body+=T(480,460,'可复现的前提：种子、预算、邻域、温度计划全部写明',21,'#5e7565');}
 else if(scene.view==='intro-goal07'){const chain=[['读轨迹','每步的判定都能解释'],['审状态机','拒绝不能偷改当前解'],['做比较','等预算+多种子']];chain.forEach(([h1,h2],i)=>{const x=90+i*270;body+=R(x,160,240,130,'#edf3e8',p*3>=i?'#72997e':'#c8d4c6')+T(x+120,205,i+1,30,'#9b6337')+T(x+120,246,h1,22,'#234e40')+T(x+120,272,h2,16,'#58796a');});body+=R(120,340,720,80,'#f6ead9','#c9a06d')+T(480,372,'三种诊断要对号入座',23,'#8a5a26')+T(480,404,'邻域不足 / 接受行为 / 预算不足——原因不同，对策不同',18,'#a04e36');}
 else if(scene.view==='state-cards')body=cards([['当前解','搜索现在站在这里；接受候选才更新'],['候选解','一个邻居编码的解码结果；用完即弃'],['历史最好合法解','单独保存：只减不增；不会被覆盖'],['能量 E','盒面积 + 100×(超宽+超高)']],p);
 else if(scene.view==='neighbor-diagram'){body=T(480,110,'交换 pos 里的两个名字',26);body+=T(240,150,'改前',22)+permChips('ABCED',330,120,['B','E']);body+=T(240,225,'改后',22)+permChips('AECBD',330,195,['E','B']);body+=T(480,290,'重新解码 → 完整布局 → 真算能量',24,p>.4?'#355d49':'#9db3a0');body+=T(480,340,'不是在旧布局上微调坐标',21,'#a05f30');}
 else if(scene.view==='delta-view'){body=T(480,120,'ΔE = E(候选) − E(当前)',32);body+=T(480,200,'ΔE ≤ 0：直接接受',26,'#355d49');body+=T(480,260,'ΔE > 0：以 exp(−ΔE/T) 的概率接受',26,'#9a5c31');if(p>.4){body+=R(150,320,660,90,'#f2f6ee')+T(480,355,'真实例子：初始236 → 第1步接受 ΔE=−187 → 49',22,'#5e7565')+T(480,392,'第6步接受 ΔE=+10 → 45（变差但被接受）',22,'#a05f30');}}
 else if(scene.view==='prob-table'){const rows=[['1','0.018','拒绝'],['4','0.37','拒绝'],['10','0.67','接受']];body=T(480,110,'同一 ΔE=4、同一 u=0.5，只改温度',24);body+=T(300,160,'T',26)+T(480,160,'p=exp(−4/T)',26)+T(680,160,'u=0.5 判定',26);rows.forEach((r,i)=>{const y=195+i*62;body+=R(180,y,620,50,p*3>=i?'#e3efdd':'#f2f6ee')+T(300,y+33,r[0],26)+T(480,y+33,r[1],26)+T(680,y+33,r[2],24,r[2]==='接受'?'#2d7865':'#a04e36');});body+=T(480,460,'温度调节接受行为；u<p 才接受',20,'#5e7565');}
 else if(scene.view==='trace-view'){const st=scene.step||6,ev=RUN07.events[st-1];body=T(480,110,'第 '+st+' 步的真实日志',26);const lines=[['T（温度）',ev.T.toFixed(3)],['候选能量',String(ev.candidateEnergy)],['ΔE',String(ev.delta)],['u（随机数）',ev.u.toFixed(3)],['p=exp(−ΔE/T)',ev.probability.toFixed(4)],['判定',ev.accepted?'接受（u<p）':'拒绝（u>p）'],['之后当前能量',String(ev.energy)],['之后最好合法',ev.bestEnergy==null?'—':String(ev.bestEnergy)]];lines.forEach((l,i)=>{const y=150+i*40;body+=R(140,y,680,34,'#f2f6ee',i===5?'#c9a06d':'#c8d4c6')+T(160,y+25,l[0],20,'#5e7565','start')+T(790,y+25,l[1],21,i===5?(ev.accepted?'#2d7865':'#a04e36'):'#355d49','end');});body+=T(480,530,ev.accepted?'当前解换成候选；最好合法解单独保存':'当前布局与能量保持原样',18);}
 else if(scene.view==='log-table'){body=T(480,110,'默认轨迹前六步（seed=7，T=12）',24);body+=T(110,160,'步',19)+T(170,160,'T',19)+T(280,160,'候选能量',19)+T(410,160,'ΔE',19)+T(510,160,'u',19)+T(620,160,'p',19)+T(710,160,'判定',19)+T(830,160,'当前',19);RUN07.events.slice(0,6).forEach((e,i)=>{const y=180+i*52;body+=R(70,y,830,44,i===5?'#f6ead9':'#f2f6ee',i===5?'#c9a06d':'#c8d4c6')+T(110,y+28,String(i+1),21)+T(170,y+28,e.T.toFixed(1),20)+T(280,y+28,String(e.candidateEnergy),20)+T(410,y+28,String(e.delta),20)+T(510,y+28,e.u.toFixed(2),20)+T(620,y+28,e.probability.toFixed(3),20)+T(710,y+28,e.accepted?'接受':'拒绝',21,e.accepted?'#2d7865':'#a04e36')+T(830,y+28,String(e.energy),20);});body+=T(480,530,'每一列都可由种子重放核对',19,'#5e7565');}
 else if(scene.view==='monotonic-chart'){const samples=[];for(let i=0;i<12;i++)samples.push(RUN07_SEED3.events[Math.min(RUN07_SEED3.events.length-1,i*10)].bestEnergy??null);let path='';let firstY=null;samples.forEach((v,i)=>{if(v==null)return;const x=120+i*62,y=400-(v-20)*9;if(firstY==null)firstY=y;path+=(path?'L':'M')+x+' '+y;body+=T(x,438,String(v),15,'#5e7565');});body+=`<path d="${path}" stroke="#2d7865" stroke-width="2.5" fill="none"/>`;body+=T(480,100,'seed=3 的历史最好合法面积（每10步取样）',24);body+=T(480,480,'最好只减不增；本次最终当前能量是 27，比最好 25 差',21,p>.5?'#a04e36':'#9db3a0');body+=T(480,515,'报告"算法结果"时用历史最好',19,'#5e7565');}
 else if(scene.view==='budget-cards')body=cards([['初始温度 T0','起点宽容度；本课默认 12'],['冷却率','每步 T←T×0.97；不是固定温度'],['总步数预算','本课默认 120 步，花完即停'],['停止条件','预算用尽；没有"跑到位了"这种说法']],p);
 else if(scene.view==='compare-table07'){body=T(480,110,'等预算比较：种子{3,7,11}，各120步',24);body+=T(300,160,'种子',24)+T(480,160,'T=12 最好合法',24)+T(700,160,'T=2 最好合法',24);COMPARISON07.seeds.forEach((sd,i)=>{const y=195+i*62;body+=R(180,y,620,50,p*3>=i?'#e3efdd':'#f2f6ee')+T(300,y+33,String(sd),26)+T(480,y+33,String(COMPARISON07.T12[i]),26,'#2d7865')+T(700,y+33,String(COMPARISON07.T2[i]),26);});body+=R(180,390,620,50,'#f6ead9','#c9a06d')+T(300,422,'合计',24,'#8a5a26')+T(480,422,String(COMPARISON07.sumT12),26)+T(700,422,String(COMPARISON07.sumT2),26);body+=T(480,480,'结论只属于这组数据与参数；多种子才能谈稳定',20,'#5e7565');}
 else if(scene.view==='penalty-cards')body=cards([['本课能量','盒面积 + 100×(超宽+超高)；无线长/拥塞'],['罚100 时','越界候选 236，输给合法的 40'],['罚改 1 时','同一个候选 38 < 40：越界反而胜出'],['100 是选择','不是通用最佳值；换模型要重新论证']],p);
 else if(scene.view==='reach-cards')body=cards([['接受行为','低温→变差难被接受→走得慢'],['可达性','邻域够不着的目标，调温无济于事'],['教材对照','限定"只换固定原点上已有模块"的邻域会锁死'],['本站邻域','任意交换序列对元素，没有那种锁死']],p);
 else if(scene.view==='repro-cards')body=cards([['同种子重放','日志逐步一致：这是复现'],['换种子换参数','seed=3 在 T=2 下最好只有 28'],['一次运行','不能证明算法优越，更不是全局最优'],['证据','等预算+多种子+完整日志']],p);
 return`<defs><pattern id="collision" width="8" height="8" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="8" height="8" fill="#efc2ad"/><path d="M0 0V8" stroke="#a74330" stroke-width="3"/></pattern></defs>${T(35,44,trial?'自己的尝试':scene.title,28,'#1d3c31','start')}${T(925,44,'第 '+scene.chapter+' / 8 章',13,'#6b8373','end')}${body}${T(480,530,trial?'试试手动调整，再想想编码怎么改':scene.note,18)}`;}
export function reportTrial(rows,scene){const r=metricsReport(rows,scene.outline||[10,8],scene.catalog);return r.legal?'当前摆放合法；搜索改的是编码——这里只是帮你感受布局。':'当前不能计有效分数：'+r.errors.map(describeError02).join('，');}